schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/evolutionary-architecture-fitness-functions.json",
  "title": "Fitness-function suite spec",
  "type": "object",
  "required": ["suite_id", "system", "owner", "dependency_graph", "results_store", "review", "functions"],
  "additionalProperties": false,
  "properties": {
    "__faion_header__": {"type": "object"},
    "suite_id": {"type": "string", "pattern": "^ff-[a-z0-9]+(-[a-z0-9]+)*$"},
    "system": {"type": "string", "minLength": 2},
    "owner": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "dependency_graph": {
      "type": "object",
      "required": ["layers", "allowed_edges"],
      "additionalProperties": false,
      "properties": {
        "layers": {"type": "array", "minItems": 2, "items": {"type": "string", "minLength": 1}},
        "allowed_edges": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["from", "to"],
            "additionalProperties": false,
            "properties": {
              "from": {"type": "string", "minLength": 1},
              "to": {"type": "string", "minLength": 1}
            }
          }
        }
      }
    },
    "results_store": {
      "type": "object",
      "required": ["location", "keyed_by", "retention_days"],
      "additionalProperties": false,
      "properties": {
        "location": {"type": "string", "minLength": 3},
        "keyed_by": {"type": "array", "const": ["function_id", "commit"]},
        "retention_days": {"type": "integer", "minimum": 30}
      }
    },
    "review": {
      "type": "object",
      "required": ["cadence", "last_reviewed_at", "next_review_at"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
        "last_reviewed_at": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
        "next_review_at": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
      }
    },
    "functions": {
      "type": "array",
      "minItems": 1,
      "contains": {"type": "object", "properties": {"kind": {"const": "structural"}}, "required": ["kind"]},
      "items": {
        "type": "object",
        "required": ["id", "characteristic", "metric", "unit", "kind", "mode", "tool", "threshold", "baseline", "threshold_mode", "consequence", "trigger", "scope", "owner", "consecutive_red_reviews"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"},
          "characteristic": {"type": "string", "minLength": 3, "pattern": "^(?![Mm]aintainab|[Ss]calab|[Mm]odular|[Cc]lean|[Qq]uality|[Rr]obust|[Ff]lexib|[Rr]eliab).*$"},
          "metric": {"type": "string", "minLength": 3},
          "unit": {"type": "string", "minLength": 1},
          "kind": {"type": "string", "enum": ["structural", "complexity", "performance", "coverage", "delivery", "security", "operability"]},
          "mode": {"type": "string", "enum": ["automated", "manual"]},
          "tool": {"type": "string", "minLength": 2},
          "command": {"type": "string", "minLength": 4},
          "review_cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
          "threshold": {
            "type": "object",
            "required": ["operator", "value"],
            "additionalProperties": false,
            "properties": {
              "operator": {"type": "string", "enum": ["<", "<=", ">", ">=", "=="]},
              "value": {"type": "number"}
            }
          },
          "baseline": {
            "type": "object",
            "required": ["value", "measured_at"],
            "additionalProperties": false,
            "properties": {
              "value": {"type": "number"},
              "measured_at": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
            }
          },
          "threshold_mode": {"type": "string", "enum": ["absolute", "ratchet"]},
          "absolute_from": {"type": "string", "minLength": 4},
          "consequence": {"type": "string", "enum": ["blocking", "informational"]},
          "trigger": {"type": "string", "enum": ["triggered", "continual"]},
          "scope": {"type": "string", "enum": ["atomic", "holistic"]},
          "owner": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
          "consecutive_red_reviews": {"type": "integer", "minimum": 0},
          "action": {"type": "string", "enum": ["fix", "rebaseline", "delete"]}
        },
        "allOf": [
          {"if": {"properties": {"mode": {"const": "automated"}}}, "then": {"required": ["command"]}},
          {"if": {"properties": {"mode": {"const": "manual"}}}, "then": {"required": ["review_cadence"]}},
          {"if": {"properties": {"threshold_mode": {"const": "ratchet"}}}, "then": {"required": ["absolute_from"]}},
          {"if": {"properties": {"scope": {"const": "holistic"}}}, "then": {"properties": {"trigger": {"const": "continual"}}}},
          {"if": {"properties": {"consecutive_red_reviews": {"minimum": 2}}}, "then": {"required": ["action"]}}
        ]
      }
    }
  }
}
